  """Generates a function that clips to [a_min, a_max] with no grad effects."""

  @jax.custom_jvp
  def clip_nograd(a):
    """Clamps `a` from above and below."""
    return jnp.clip(a, a_min, a_max)

  @clip_nograd.defjvp
